"""Grandfather-father-son snapshot retention. See task.md."""

from __future__ import annotations

import re
from datetime import datetime
from typing import NamedTuple


class RetentionError(ValueError):
    """Raised for an unusable policy or an unusable list of snapshots."""


class Kept(NamedTuple):
    snapshot: str
    reasons: tuple[str, ...]


_RULES = ("last", "hourly", "daily", "weekly", "monthly", "yearly")
_FORMAT = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})T([0-9]{2}):([0-9]{2}):([0-9]{2})")


def _bucket(rule: str, dt: datetime):
    if rule == "hourly":
        return (dt.year, dt.month, dt.day, dt.hour)
    if rule == "daily":
        return (dt.year, dt.month, dt.day)
    if rule == "weekly":
        iso = dt.isocalendar()
        return (iso[0], iso[1])
    if rule == "monthly":
        return (dt.year, dt.month)
    return dt.year


def retain(snapshots: list[str], policy: dict) -> list[Kept]:
    """Return the snapshots `policy` keeps, newest first, with the rules that keep each."""
    if not isinstance(policy, dict):
        raise RetentionError("policy must be a dict")
    for key, value in policy.items():
        if not isinstance(key, str) or key not in _RULES:
            raise RetentionError(f"unknown policy key: {key!r}")
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise RetentionError(f"invalid value for {key!r}: {value!r}")
    if not any(v > 0 for v in policy.values()):
        raise RetentionError("policy keeps nothing")

    parsed: dict[str, datetime] = {}
    for snap in snapshots:
        if not isinstance(snap, str):
            raise RetentionError(f"snapshot is not a string: {snap!r}")
        m = _FORMAT.fullmatch(snap)
        if not m:
            raise RetentionError(f"bad snapshot: {snap!r}")
        try:
            dt = datetime(*map(int, m.groups()))
        except ValueError:
            raise RetentionError(f"bad snapshot: {snap!r}") from None
        if snap in parsed:
            raise RetentionError(f"duplicate snapshot: {snap!r}")
        parsed[snap] = dt

    newest_first = sorted(parsed, reverse=True)
    reasons: dict[str, list[str]] = {}
    for rule in _RULES:
        n = policy.get(rule, 0)
        if n == 0:
            continue
        if rule == "last":
            chosen = newest_first[:n]
        else:
            chosen = []
            seen = set()
            for snap in newest_first:
                b = _bucket(rule, parsed[snap])
                if b in seen:
                    continue
                if len(seen) == n:
                    break
                seen.add(b)
                chosen.append(snap)
        for snap in chosen:
            reasons.setdefault(snap, []).append(rule)
    return [Kept(s, tuple(reasons[s])) for s in newest_first if s in reasons]
